mapper.select:
SELECT CATEGORY_ID, CATEGORY_NAME, DESCRIPTION, USE_YN, CREATED_AT
FROM CATEGORIES
WHERE CATEGORY_ID = #{categoryId,jdbcType=NUMERIC}

mapper.update:
UPDATE CATEGORIES
SET USE_YN = #{useYn,jdbcType=VARCHAR}
WHERE CATEGORY_ID = #{categoryId,jdbcType=NUMERIC}

UPDATE CATEGORIES
SET USE_YN = 'D'
WHERE CATEGORY_ID = #{categoryId,jdbcType=NUMERIC}

